// The brand mark of a model that a router provider serves. Magpie routes one id to many model makers,
// such as `codex/gpt-6-sol` or `workbuddy-ai/hy3`, so the provider mark does not tell them apart.

import { type ProviderLogoPath, type ProviderLogoShape, providerLogoShape } from "./provider-logo-shape";

export type ModelBrandMark =
  | "claude"
  | "openai"
  | "deepseek"
  | "grok"
  | "gemini"
  | "zhipu"
  | "hunyuan"
  | "qwen"
  | "kimi"
  | "minimax"
  | "doubao"
  | "mistral"
  | "meta"
  | "stepfun"
  | "wenxin"
  | "mimo"
  | "magpie";

/** The families in the order they are tried on each word of a model id or name. */
const FAMILY_RULES: readonly (readonly [ModelBrandMark, (word: string) => boolean])[] = [
  ["claude", (word) => /^(claude|opus|sonnet|haiku)/.test(word)],
  ["openai", (word) => /^(gpt|chatgpt|openai|codex)/.test(word) || /^o\d+$/.test(word)],
  ["deepseek", (word) => word.startsWith("deepseek")],
  ["grok", (word) => /^(grok|xai)/.test(word)],
  ["gemini", (word) => /^(gemini|gemma)/.test(word)],
  ["zhipu", (word) => /^(glm|chatglm|zhipu)/.test(word)],
  ["hunyuan", (word) => /^hy\d*$/.test(word) || word.startsWith("hunyuan")],
  ["qwen", (word) => /^(qwen|qwq)/.test(word)],
  ["kimi", (word) => /^(kimi|moonshot)/.test(word)],
  ["minimax", (word) => word.startsWith("minimax")],
  ["doubao", (word) => word.startsWith("doubao") || /^seed\d*$/.test(word)],
  ["mistral", (word) => /^(mistral|ministral|magistral|codestral|devstral|pixtral)/.test(word)],
  ["meta", (word) => word.startsWith("llama")],
  ["stepfun", (word) => /^step\d*$/.test(word) || word.startsWith("stepfun")],
  ["wenxin", (word) => /^(ernie|wenxin)/.test(word)],
  ["mimo", (word) => word.startsWith("mimo")],
];

function familyOf(text: string): ModelBrandMark | null {
  for (const word of text.toLowerCase().split(/[^a-z0-9]+/)) {
    if (!word) continue;
    const rule = FAMILY_RULES.find(([, matches]) => matches(word));
    if (rule) return rule[0];
  }
  return null;
}

/**
 * The family of a model, from its id and its display name, without regard to case. The model part
 * of the id is tried first, then the display name, then the route before the last `/`. A model of
 * no known family keeps the Magpie mark.
 */
export function modelBrandMark(modelId: string, displayName?: string | null): ModelBrandMark {
  const slash = modelId.lastIndexOf("/");
  const model = modelId.slice(slash + 1);
  const route = slash < 0 ? "" : modelId.slice(0, slash);
  return familyOf(model) ?? familyOf(displayName ?? "") ?? familyOf(route) ?? "magpie";
}

