const LOBE_PATHS = {
  zhipu: ZHIPU_PATHS,
  hunyuan: HUNYUAN_PATHS,
  qwen: QWEN_PATHS,
  kimi: KIMI_PATHS,
  minimax: MINIMAX_PATHS,
  doubao: DOUBAO_PATHS,
  mistral: MISTRAL_PATHS,
  meta: META_PATHS,
  stepfun: STEPFUN_PATHS,
  wenxin: WENXIN_PATHS,
  mimo: MIMO_PATHS,
} as const satisfies Record<string, readonly ProviderLogoPath[]>;

/** The view box and paths of a model mark, in one colour, as `providerLogoShape` gives them. */
export function modelBrandMarkShape(mark: ModelBrandMark): ProviderLogoShape {
  switch (mark) {
    case "claude":
      return providerLogoShape("claude");
    case "openai":
      return providerLogoShape("codex");
    case "deepseek":
      return providerLogoShape("deepseek");
    case "grok":
      return providerLogoShape("grok");
    case "gemini":
      return providerLogoShape("antigravity");
    case "magpie":
      return providerLogoShape("magpie");
    default:
      return { viewBox: GRID_24, paths: LOBE_PATHS[mark] };
  }
}
